def move_to_nodes(apps, schema_editor):
    """Прежний ресурс: текст ответа и плоский список файлов. Теперь это корневой узел (текст, при listing с {listing}) и узлы-файлы."""
    NetResource = apps.get_model("machines", "NetResource")
    NetResourceFile = apps.get_model("machines", "NetResourceFile")
    NetNode = apps.get_model("machines", "NetNode")

    for resource in NetResource.objects.all():
        text = resource.response
        if resource.listing:
            text = (text.rstrip() + "\n\n" if text.strip() else "") + "{listing}"
        if text.strip():
            NetNode.objects.create(resource=resource, path="", response=text)

    for item in NetResourceFile.objects.all():
        NetNode.objects.get_or_create(resource_id=item.resource_id, path=item.name, defaults={"file_id": item.file_id})


